={{ JSON.stringify({
  model: "claude-haiku-4-5-20251001",
  max_tokens: 1500,
  tools: [
    {
      name: "submit_post",
      description: "生成したSNS投稿案を提出する",
      input_schema: {
        type: "object",
        properties: {
          pattern_used: { type: "string", description: "採用した型の名前（マークは含めない）" },
          hook: { type: "string" },
          body: { type: "string" },
          cta: { type: "string" },
          hashtags: { type: "array", items: { type: "string" } },
          image_prompt: { type: "string" }
        },
        required: ["pattern_used", "hook", "body", "cta", "hashtags", "image_prompt"]
      }
    }
  ],
  tool_choice: { type: "tool", name: "submit_post" },
  system: "あなたは「白石玲子｜キャリア未来鑑定士」です。**キャラクター名は必ず「白石玲子」という漢字表記のまま使うこと。英訳・意訳・ローマ字化は絶対にしない（誤り例:「White Stone Leiko」等）。** 一人称は「私」。丁寧な「です・ます」調（だよ・ね等は使わない）。占い師というより経験豊富な転職アドバイザーのように話す。不安を煽りすぎず、断定しすぎない（Agitationではなく共感=Affinityを優先する）。詳細ルールは automation/n8n/docs/workflow-design.md 1章 (reiko-character.md参照) に従うこと。\n\n固有名詞化の禁止（例外あり）: 元ネタに具体的な企業名・サービス名・ニュース名が含まれていても、無条件にそのまま列挙しない。判断基準は「一般読者の大半が、業界に詳しくなくてもその名前を知っている/直近でよく見聞きしている」レベルかどうか。該当する場合（誰もが知る国民的ニュース、日常的に使われる超大手ブランドが絡む大きな話題など、今まさに話題になっていて多くの人が認知しているもの）は、固有名詞をそのまま使ってよい。検索されるキーワードと一致しやすくSEO・アルゴリズム上有利になるため、むしろ積極的に使うこと。該当しない場合（例:「シャープ、アリババのAI戦略シフト」のように、業界内では話題でも一般読者には馴染みが薄いニュース）は、「大手企業のAI活用が進むニュース」のように誰でもわかる一般化した言い方に変換してから使うこと。\n\n次のプラットフォーム別の「型」の中から、投稿タイプ・元ネタに最も合うものを1つ選んで書くこと。型には✅（そのまま使ってよい）⚠️（断定・煽り表現を柔らかい言い換えに変換してから使う）🚫（使わない）のマークが付いている。🚫の型は選ばないこと。⚠️の型を選ぶ場合は必ず指示どおり表現を和らげること。\n\n" + $json.platform_guide,
  messages: [
    { role: "user", content: `投稿タイプ: ${$json.post_type}\nプラットフォーム: ${$json.platform}\n想定読者: ${$json.target_persona}\n元ネタ: ${$json.source_summary}` }
  ]
}) }}

parameters.jsCode:
// Claudeのtool_use出力(input)は既にパース済みオブジェクトなので、JSON.parseは不要
const results = [];
for (const item of $input.all()) {
  const content = item.json.content ?? [];
  const toolUse = content.find(b => b.type === 'tool_use' && b.name === 'submit_post');
  if (!toolUse) {
    throw new Error('Claude応答にtool_useブロックが見つかりませんでした: ' + JSON.stringify(content).slice(0, 300));
  }
  const p = toolUse.input;
  const src = $('プラットフォーム別パターン選択').first().json;
  results.push({
    json: {
      name: (p.hook || p.body || '無題').slice(0, 60),
      platform: src.platform,
      post_type: src.post_type,
      pattern_used: p.pattern_used ?? '',
      hook: p.hook ?? '',
      body: p.body ?? '',
      cta: p.cta ?? '',
      hashtags: Array.isArray(p.hashtags) ? p.hashtags.join(', ') : (p.hashtags ?? ''),
      image_prompt: p.image_prompt ?? '',
      target_persona: src.target_persona,
      source_urls: '',
      status: 'draft',
      // Workflow01から渡された場合のみ値が入る（手動テスト時は空でよい）
      article_image_url: src.article_image_url ?? '',
      scheduled_post_datetime: src.suggested_post_datetime ?? ''
    }
  });
}
return results;
